mkdir -p probe/c
UA="deck-bot/1.0 (student presentation; github.com/hiya77)"
q(){ sleep 2; curl -fsSL -A "$UA" "https://commons.wikimedia.org/w/api.php?action=query&format=json&generator=search&gsrnamespace=6&gsrlimit=25&gsrsearch=$(python3 -c 'import urllib.parse,sys;print(urllib.parse.quote(sys.argv[1]))' "$2")&prop=imageinfo&iiprop=url|size|extmetadata&iiurlwidth=1280&iiextmetadatafilter=LicenseShortName|Artist" -o "probe/$1.json" || echo "FAIL $1"; }
d(){ sleep 1; curl -fsSL -A "$UA" -o "probe/c/$1" "$2" || echo "FAIL $1"; }
